import { getBankIndex } from "./core.mjs";
import { icon, esc, attr, button, head } from "./ui.mjs";

export function createLibraryPages({ getBank, sync, getConfiguredAPI, openDialog, shortDate }) {
  function cloudCard() {
    return `<section class="card library-card cloud-card"><div class="card-head"><h2>跨设备学习进度</h2><span class="pill ${sync.connected ? "green" : ""}">${sync.connected ? "已连接" : "可选"}</span></div><p class="subtitle">${sync.connected ? `服务器进度版本：${sync.version}。上传会替换服务器进度；恢复会替换本机进度。` : "连接自己的同步服务器，在不同设备间接续学习。未连接时，所有刷题功能仍可正常使用。"}</p><div class="flex" style="margin-top:18px">${sync.connected ? `${button("上传本机进度", "cloud-upload", "", "btn primary")}${button("恢复服务器进度", "cloud-download")}${button("断开连接", "cloud-disconnect", "", "text-btn")}` : button("连接同步服务器", "cloud-connect", "", "btn")}</div><p class="format-note" style="margin-top:14px">同步密钥只在当前页面内存中使用，刷新后需重新连接。支持内置知行学习题库；自定义题库请使用完整备份。</p></section>`;
  }
  function showCloudConnect() {
    openDialog("连接同步服务器", `<p>输入自己的服务器地址和个人同步密钥。每位学习者使用不同密钥。</p><div class="field"><label for="cloud-api">服务器地址</label><input id="cloud-api" class="input" type="url" value="${attr(sync.base || getConfiguredAPI())}" placeholder="https://api.example.com" autocomplete="off"></div><div class="field"><label for="cloud-token">个人同步密钥</label><input id="cloud-token" class="input" type="password" autocomplete="off" spellcheck="false"></div><p class="format-note">连接只检查服务器进度，不会上传或替换学习记录。</p>`, `${button("取消", "close-dialog")}${button("连接", "cloud-do-connect", "", "btn primary")}`);
  }
  function libraryPage() {
    const bank = getBank();
    return `${head("让原题，回到你的学习节奏。", "保留原题内容、标准答案和解析，再用自己的方式练习。", bank.questions.length ? button(`${icon("download", 14)} 导出题库`, "export-bank", "", "btn") : "")}<section class="card library-hero"><div class="empty-symbol">${icon(bank.questions.length ? "check" : "folder", 29)}</div><div class="grow"><span class="pill ${bank.questions.length ? "green" : "coral"}">${bank.questions.length ? "题库已就绪" : "等待原题数据"}</span><h2 style="margin-top:10px">${bank.questions.length ? `${bank.questions.length.toLocaleString()} 道原题，已加入学习空间` : "网站已就绪，题库由你补充"}</h2><p class="subtitle">${bank.questions.length ? `${esc(bank.managedBundle !== false && bank.revision?.startsWith("pdf-") ? "知行学习题库" : bank.source.name || "已导入题库")} · ${bank.subjects.length} 个科目 · 导入于 ${shortDate(bank.importedAt)}` : "目前没有填入示例题。导入后，科目、章节、题干、答案与解析均以原始数据为准。"}</p></div></section>${cloudCard()}<div class="grid-2"><section class="card library-card"><div class="card-head"><h2>导入原题库</h2>${icon("upload", 18)}</div><div class="upload-zone" id="drop-zone" tabindex="0" role="button" aria-label="选择或拖入 JSON 题库">${icon("upload", 29)}<h3>把题库带到这里</h3><p>拖入 JSON 文件，或点击选择。导入前会检查题型、答案、选项和章节关联。</p>${button("选择题库文件", "choose-file", "", "btn primary")}<div class="muted" style="font-size:9px;margin-top:12px">JSON 格式 · 最大 50 MB · 最多 100,000 题</div></div><div class="flex" style="justify-content:space-between">${button(`${icon("download", 13)} 下载空白模板`, "download-template", "", "text-btn")}${button("查看格式说明", "import-help", "", "text-btn")}</div><p class="format-note" style="margin-top:18px">支持单选、多选、判断、填空和解答题。公式支持 LaTeX，题干与解析可保留常见 HTML 排版。解答题使用对照自评；填空题可配置多个可接受答案。</p></section><div class="stack"><section class="card library-card"><div class="card-head"><h2>学习数据，留在自己手里</h2>${icon("lock", 16)}</div><div class="data-actions"><button class="data-action" data-action="export-backup"><b>${icon("download", 15)} 导出完整备份</b><p>题库、作答记录、考试与知识点阅读进度。</p></button>${bank.managedBundle !== false && bank.revision?.startsWith("pdf-") ? `<button class="data-action" data-action="export-progress"><b>${icon("download", 15)} 导出轻量进度备份</b><p>仅保存学习记录，恢复时需要相同版本的内置题库。</p></button>` : ""}<button class="data-action" data-action="restore-backup"><b>${icon("refresh", 15)} 恢复学习数据</b><p>选择之前导出的知行学习备份，继续上次的进度。</p></button></div><p class="format-note" style="margin-top:14px">学习数据保存在当前浏览器。更换设备或清理浏览器前，请先导出备份。</p></section><section class="card library-card"><div class="card-head"><h2>当前题库</h2><span class="pill">${bank.questions.length} 题</span></div>${bank.subjects.map((s) => `<div class="chapter-row"><span class="grow">${esc(s.name)}</span><span class="muted">${getBankIndex(bank).subjectQuestions.get(s.id).length} 题</span></div>`).join("")}<div style="margin-top:17px">${button(`${icon("trash", 12)} 清空学习记录`, "reset-data", "", "text-btn")}</div></section></div></div>`;
  }

  return { libraryPage, showCloudConnect };
}
